  "AGENTS.md": "# Working on example-shop\n\n- Money is integer cents (`Money`), never floats.\n- Run `npm test`, `npx tsc --noEmit` and `npm run lint` before you commit.\n- The mobile app imports from `src/cart` and `src/api`: keep their exports stable.\n",
  "src/cart/totals.ts": "import type { CartLine } from './types';\n\n// Totals in cents. Kept for the mobile app; new code uses cartTotals().\nexport function calculateTotals(lines: CartLine[]) {\n  const subtotal = lines.reduce((sum, l) => sum + l.unitPrice * l.quantity, 0);\n  return { subtotal, total: subtotal };\n}\n",
  "src/cart/index.ts": "export { calculateTotals } from './totals';\nexport { useCart } from './useCart';\n",
  "src/cart/useCart.ts": "import { useState } from 'react';\nimport { calculateTotals } from './totals';\n\nexport function useCart() {\n  const [lines, setLines] = useState([]);\n  return { lines, setLines, totals: calculateTotals(lines) };\n}\n",
  "src/promo/apply.ts": "import { rulesFor } from './rules';\n\nexport function applyPromo(code: string, subtotal: number) {\n  const rule = rulesFor(code);\n  return rule ? Math.max(0, subtotal - rule.discount(subtotal)) : subtotal;\n}\n",
  "src/promo/rules.ts": "export const rules = {\n  SPRING10: { discount: (s: number) => Math.round(s * 0.1) },\n  FREESHIP: { discount: () => 0, freeShipping: true },\n};\nexport const rulesFor = (code: string) => rules[code.toUpperCase()];\n",
  "src/checkout/CheckoutPage.tsx": "import { AddressForm } from './AddressForm';\n\nexport function CheckoutPage() {\n  return (<main><h1>Checkout</h1><AddressForm /></main>);\n}\n",
  "src/checkout/AddressForm.tsx": "export function AddressForm() {\n  return (<form aria-label=\"Shipping address\">{/* fields */}</form>);\n}\n",
  "src/checkout/postcode.ts": "export const normalizePostcode = (value: string) => value.trim().toUpperCase();\n",
  "src/tax/round.ts": "// Rounds a tax amount in cents.\nexport const roundTax = (cents: number) => Math.round(cents);\n",
  "src/search/rank.ts": "import { tokenize } from './tokenize';\n\nexport function score(query: string, title: string) {\n  const words = tokenize(query);\n  return words.filter((w) => title.toLowerCase().includes(w)).length;\n}\n",
  "src/search/tokenize.ts": "export const tokenize = (text: string) => text.toLowerCase().split(/\\s+/).filter(Boolean);\n",
  "src/address/store.ts": "export async function saveAddress(customerId: string, address: Address) {\n  return db.addresses.insert({ customerId, ...address });\n}\n",
  "src/api/schema.graphql": "type Cart {\n  id: ID!\n  lines: [CartLine!]!\n  total: Float!\n}\n",
  "playwright.config.ts": "import { defineConfig } from '@playwright/test';\nexport default defineConfig({ testDir: 'e2e', webServer: { command: 'npm run dev', port: 5173 } });\n",
